I'm trying to create a script that allows users to drop their own texture on my model, but i am a little stuck here.

My code so far:

``` javascript
window.ondrop = function( event ){
    event.preventDefault();

    for (i = 0; i < event.dataTransfer.files.length; i ++){
        var file = event.dataTransfer.files[ i ];
        var extention =  file.name.split( '.' ).pop();
        if (extention == 'jpg') loadImage( file );
    }
}

function loadImage( file ){
    var reader = new FileReader();
    reader.readAsDataURL( file );
    reader.onload = function( event ){

        var img = new Image();
        img.src = event.currentTarget.result;
        img.onload = function(){

            var material = new THREE.MeshBasicMaterial( { map: new THREE.Texture( img ) } );
            //var material = new THREE.MeshBasicMaterial( { color: new THREE.Color( 0xffffff ), wireframe: true } ); //< This works!
            three.object.material = material;

        }
    }
}
```

After i drop an image on my window, and the script applies the new material on my model, my model turns black.
I think this line causes the error

``` javascript
new THREE.Texture( img )
```

But i can't find a solution anywhere in the documentation.

